class Solution {
  public int neighborNotesEvenKeyCensus(int[] readings) {
    int[] a=readings; List<Integer> out=new ArrayList<>();
    {for(int i=1;i<a.length;i++)out.add(a[i]-a[i-1]);}
    int answer=0;for(int x:out)if(x%2==0)answer++;return answer;
  }
